text:
Layer 1 sits near 94.5% with train about equal to held, so it underfits and needs better units. Now I test hyperplanes that bisect sampled point pairs (random and nearest opposite-class) with bias at the midpoint, and subclass-mean LDA directions, each with ridge readout on layer 1 only.

```python
import numpy as np, time
from scipy.special import expit
t=time.time()
X=np.load("train_images.npy").reshape(60000,-1).astype(np.float64)/255
y=np.load("train_labels.npy").astype(int)
perm=np.load("perm.npy");tr,ho=perm[:50000],perm[50000:]
lam=np.load("pca_lam.npy");V=np.load("pca_V.npy");mu=np.load("pca_mu.npy").astype(np.float64)
Y=np.eye(10)[y]
def silu(x): return x*expit(x)
def ridge(H,Yt,l):
    m=H.mean(0);Hc=H-m;ym=Yt.mean(0)
    A=Hc.T@Hc; A=A+l*np.trace(A)/len(A)*np.eye(len(A))
    W=np.linalg.solve(A,Hc.T@(Yt-ym)); b=ym-m@W
    return W,b
def acc(H,W,b,yy): return round(float(((H@W+b).argmax(1)==yy).mean()),4)
def score(H):
    W,b=ridge(H[tr],Y[tr],1e-6); return acc(H[tr],W,b,y[tr]),acc(H[ho],W,b,y[ho])
rng=np.random.default_rng(2)
def pca_space(k,p):
    return (X-mu)@V[:,:k]/lam[:k]**p
def within_white(k,shrink=0.02):
    Z=(X-mu)@V[:,:k]
    S=np.zeros((k,k))
    for c in range(10):
        i=tr[y[tr]==c];S+=np.cov(Z[i].T)*len(i)
    S/=len(tr);S+=shrink*np.trace(S)/k*np.eye(k)
    l,U=np.linalg.eigh(S)
    return Z@U/np.sqrt(l)
def bisect_units(Z,a,b,s,b0):
    d=Z[a]-Z[b]; mid=(Z[a]+Z[b])/2
    n2=(d*d).sum(1,keepdims=True)
    w=2*s*d/n2
    return silu((Z-mid.mean(0))@w.T-((mid-mid.mean(0))*w).sum(1)+b0)
def random_opp(n):
    a=rng.choice(tr,n);b=np.empty(n,int)
    for i in range(n):
        c=tr[y[tr]!=y[a[i]]];b[i]=rng.choice(c)
    return a,b
def near_opp(Z,n,top):
    a=rng.choice(tr,n);b=np.empty(n,int)
    Zt=Z[tr];yt=y[tr]
    for i in range(n):
        dd=((Zt-Z[a[i]])**2).sum(1);dd[yt==y[a[i]]]=np.inf
        b[i]=tr[np.argpartition(dd,top)[:top][rng.integers(top)]]
    return a,b
for name,Z in (("pca100 p.5",pca_space(100,.5)),("pca100 p.25",pca_space(100,.25)),("within k60",within_white(60))):
    a,b=random_opp(512)
    for s,b0 in ((1,0),(2,0)):
        print(name,"random-opp s",s,"b0",b0,score(bisect_units(Z,a,b,s,b0)),round(time.time()-t,1))
    a,b=near_opp(Z,512,5)
    for s,b0 in ((0.5,0),(1,0),(2,0)):
        print(name,"near-opp s",s,"b0",b0,score(bisect_units(Z,a,b,s,b0)),round(time.time()-t,1))
```

